steps.solution:
function doubleOrders(orders) {
  const doubled = []
  for (let i = 0; i < orders.length; i++) {
    doubled.push(orders[i] * 2)
  }
  return doubled
}

console.log(doubleOrders([1, 2, 3])) // [2, 4, 6]
